import fs from 'node:fs';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
import path from 'node:path';
// node tests/fixtures/share.generate.mjs /path/to/fluoddity /path/to/lz-string/libs/lz-string.js
// Run from the repository root with Node >= 26 (native TypeScript stripping).
const source = process.argv[2];
const legacySource = process.argv[3];
if (!source || !legacySource) throw new Error('Provide the original Fluoddity checkout and lz-string 1.5.0 JS module paths');
const {encodeDocument,decodeDocument} = await import(pathToFileURL(path.join(source, 'src/config/shareCodec.ts')));
const require = createRequire(import.meta.url);
const LZ = require(path.resolve(legacySource));
const document = JSON.parse(fs.readFileSync('assets/presets/Core/Starcrossed.json','utf8'));
document.notes='Original share codec parity 🧬\nΔynamics + seeds';
document.configs.push(structuredClone(document.configs[0]));
Object.assign(document.configs[1].misc,{mutation_seed:0.024925940576650873,cohorts:300000});
Object.assign(document.configs[1].force2,{cohort_fences:true,initial_conditions:3});
Object.assign(document.configs[1].misc2,{color_by_cohort:true,sensor_angle_jitter:0.123456789012345,sensor_distance_jitter:0.234567890123456});
Object.assign(document.configs[1].misc3,{radial_gravity:true,gravity_trails:0.25,color_offset:-0.5,trail_weight:1.75});
const full=encodeDocument(document);
const vectors=[];
for(let codec=1;codec<=4;codec++){
 const chunks=[full.slice(0,21)]; chunks[0][0]=codec;
 for(let c=0;c<document.configs.length;c++){
  const start=21+c*478;
  chunks.push(full.slice(start,start+320+(15+codec)*8));
  chunks.push(full.slice(start+472,start+478));
 }
 chunks.push(full.slice(21+document.configs.length*478));
 const bytes=Buffer.concat(chunks);
 vectors.push({codec,hash:'#b='+bytes.toString('base64url'),document:decodeDocument(bytes)});
}
const legacy='#c='+LZ.compressToEncodedURIComponent(JSON.stringify(document));
fs.writeFileSync('tests/fixtures/share.fixture.json',JSON.stringify({provenance:'Generated by the unmodified original src/config/shareCodec.ts encodeDocument/decodeDocument in Node 26; legacy produced by cached lz-string 1.5.0. Codec 1..3 strip only scalars appended by codec 4.',vectors,legacy,document},null,2)+'\n');
const historical = JSON.parse(fs.readFileSync('tests/fixtures/historical/AATangle.json','utf8'));
const saved = JSON.parse(fs.readFileSync('tests/fixtures/share.fixture.json','utf8'));
saved.historical = {document:historical,hash:'#b='+Buffer.from(encodeDocument(historical)).toString('base64url')};
fs.writeFileSync('tests/fixtures/share.fixture.json',JSON.stringify(saved,null,2)+'\n');
